<div class="modal fade" id="modalVenta" tabindex="-1"><div class="modal-dialog modal-dialog-centered modal-lg"><div class="modal-content"><form id="formVenta">
    <div class="modal-header"><h2 class="modal-title fs-5">Nueva venta</h2><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div>
    <div class="modal-body"><div id="errorVenta" class="alert alert-danger d-none"></div><div class="row g-3">
        <div class="col-12"><label class="form-label" for="ventaEan">EAN-13 / escáner</label><input id="ventaEan" inputmode="numeric" pattern="[0-9]{13}" maxlength="13" autocomplete="off" class="form-control form-control-lg font-monospace" placeholder="Escaneá para seleccionar el producto"></div>
        <div class="col-md-6"><label class="form-label" for="ventaCliente">Cliente</label><select class="form-select" id="ventaCliente" name="cliente_id" required></select></div>
        <div class="col-md-6"><label class="form-label" for="ventaProducto">Producto</label><select class="form-select" id="ventaProducto" name="producto_id" required></select></div>
        <div class="col-sm-4"><span class="form-label d-block">Precio</span><strong id="ventaPrecioReferencial">—</strong></div>
        <div class="col-sm-4"><span class="form-label d-block">Presentación</span><strong id="ventaUnidad">—</strong></div>
        <div class="col-sm-4"><span class="form-label d-block">Stock vendible</span><strong id="ventaStock">—</strong></div>
        <div class="col-md-4"><label class="form-label" for="ventaCantidad">Cantidad</label><input class="form-control" id="ventaCantidad" name="cantidad" type="number" min="1" value="1" required></div>
        <div class="col-md-8"><label class="form-label" for="ventaMargen">Margen sobre precio</label><div class="d-flex flex-wrap gap-2 mb-2" id="botonesMargen"><button type="button" class="btn btn-outline-primary btn-sm" data-margen="5">+5%</button><button type="button" class="btn btn-outline-primary btn-sm" data-margen="10">+10%</button><button type="button" class="btn btn-outline-primary btn-sm" data-margen="15">+15%</button><button type="button" class="btn btn-outline-primary btn-sm" data-margen="20">+20%</button></div><div class="input-group"><input class="form-control" id="ventaMargen" name="porcentaje_vendedor" type="number" min="0" step="0.01" value="0" required><span class="input-group-text">%</span></div><small id="ayudaMargen" class="texto-secundario"></small></div>
    </div><div class="bg-light rounded-3 p-3 mt-4"><div class="row g-2"><div class="col-6">Precio con margen</div><div class="col-6 text-end fw-semibold" id="ventaPrecioMargen">—</div><div class="col-6">Bonificación automática</div><div class="col-6 text-end fw-semibold" id="ventaBonificacion">0%</div><div class="col-6">Precio final unitario</div><div class="col-6 text-end fw-semibold" id="ventaPrecioFinal">—</div><div class="col-6 fs-5">Total</div><div class="col-6 text-end fw-bold fs-5" id="ventaTotal">—</div></div></div></div>
    <div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancelar</button><button class="btn btn-primary">Registrar venta</button></div>
</form></div></div></div>

<div class="modal fade" id="modalModificarVenta" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form id="formModificarVenta"><div class="modal-header"><h2 class="modal-title fs-5">Modificar cantidad</h2><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div id="errorModificarVenta" class="alert alert-danger d-none"></div><input type="hidden" name="venta_id" id="modificarVentaId"><input type="hidden" name="accion" value="modificar_cantidad"><label for="modificarCantidad" class="form-label">Nueva cantidad</label><input type="number" min="1" id="modificarCantidad" name="cantidad" class="form-control" required><p class="texto-secundario small mt-2">La bonificación se recalculará según las reglas activas. El precio y el margen original no cambian.</p><label for="motivoModificacion" class="form-label">Motivo (opcional)</label><textarea id="motivoModificacion" name="motivo" class="form-control" maxlength="500"></textarea></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Volver</button><button class="btn btn-primary">Guardar cambio</button></div></form></div></div></div>
<div class="modal fade" id="modalCancelarVenta" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form id="formCancelarVenta"><div class="modal-header"><h2 class="modal-title fs-5">Cancelar venta</h2><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div id="errorCancelarVenta" class="alert alert-danger d-none"></div><input type="hidden" name="venta_id" id="cancelarVentaId"><input type="hidden" name="accion" value="cancelar"><p class="texto-secundario">La venta permanecerá en el historial y el stock se devolverá una sola vez al lote correspondiente.</p><label for="motivoCancelacion" class="form-label">Motivo</label><textarea id="motivoCancelacion" name="motivo" class="form-control" maxlength="500"></textarea></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Volver</button><button class="btn btn-danger">Confirmar cancelación</button></div></form></div></div></div>
